const lines = fs.readFileSync('bizno_filtered_result_nice.tsv', 'utf-8').split('\n').filter(l => l.trim().length > 0);
console.log('Processing 500 rows...');

// Category mapping dictionary for common Korean industries (Bizno standard)
const categoryMap = {
